<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useLegionSession } from '../../composables/useLegionSession';
import { advanceLegion, commandLegion, LEGION_COMMANDS, legionCardLevel, legionChapter, legionPower, legionRegion, legionSlots, legionStats, legionTrainingCost, legionUnlocked, strengthenLegion, summonLegion, trainLegion } from '../../utils/rest/legion';
import { LEGION_CARDS, LEGION_STRATEGIES, LEGION_UNITS, type LegionStrategy, type LegionUnitKind } from '../../utils/rest/legionContent';
import LegionBattlefield from './LegionBattlefield.vue';
import LegionFigure from './LegionFigure.vue';
const props = defineProps<{ paused: boolean }>();
const emit = defineEmits<{ 'pause-change': [paused: boolean] }>();
const session = useLegionSession(), state = session.state, detach = session.attach();
onBeforeUnmount(detach);
if(props.paused) session.mutate(s=>{s.paused=true;});
onMounted(()=>emit('pause-change',state.value.paused));
watch(() => props.paused, value => session.mutate(s => { s.paused = value; }));
const panel = ref<'army'|'skills'|'log'|'rules'|null>(null), selected = ref<LegionUnitKind>('guard');
const detailPanel=ref<HTMLElement>();
watch(panel,async value=>{if(value){await nextTick();detailPanel.value?.scrollIntoView?.({block:'start',behavior:'smooth'});}});
const selectedUnit = computed(() => LEGION_UNITS.find(u => u.id === selected.value)!);
const selectedStats = computed(() => legionStats(state.value, selected.value));
const format = (n: number) => n >= 1e8 ? `${(n/1e8).toFixed(1)}亿` : n >= 10000 ? `${(n/10000).toFixed(1)}万` : Math.floor(n).toLocaleString('zh-CN');
const duration = computed(() => `${Math.floor(state.value.elapsed/60)}:${String(Math.floor(state.value.elapsed%60)).padStart(2,'0')}`);
const skillCards = computed(() => [...LEGION_CARDS].sort((a,b) => Number(b.family===state.value.strategy)-Number(a.family===state.value.strategy)));
const canSummon = (id:LegionUnitKind) => !state.value.paused && state.value.phase!=='recover' && legionUnlocked(state.value,id) && state.value.recruitClock<=0 && legionSlots(state.value)<24 && state.value.essence>=LEGION_UNITS.find(u=>u.id===id)!.cost;
function togglePanel(value: typeof panel.value) { panel.value = panel.value === value ? null : value; }
function chooseUnit(id: LegionUnitKind) { selected.value = id; panel.value = 'army'; }
function togglePause() { session.mutate(s=>{s.paused=!s.paused;});emit('pause-change',state.value.paused); }
defineExpose({ restart: session.restart });
</script>
<template>
  <div class="legion-game" tabindex="0" data-game-focus aria-label="召唤军团，手动指挥远征">
    <div class="legion-topline"><strong>{{legionRegion(state).name}} · {{legionChapter(state)}}</strong><span class="legion-running">{{state.paused?'远征暂停':'手动指挥 · 自动战斗'}}</span><label class="legion-speed">速度 <select aria-label="远征速度" :value="state.speed" @change="session.mutate(s=>s.speed=Number(($event.target as HTMLSelectElement).value) as 1|2)"><option :value="1">1倍</option><option :value="2">2倍</option></select></label></div>
    <div class="legion-resources"><span>金币 <b>{{format(state.coins)}}</b></span><span>召唤精华 <b>{{format(state.essence)}}</b></span><span>军团战力 <b>{{format(legionPower(state))}}</b></span><span>远征 <b>{{duration}}</b></span></div>
    <div class="legion-layout">
      <LegionBattlefield :state="state"/>
      <aside class="legion-strategy" aria-label="战场指挥">
        <label for="legion-strategy"><strong>构筑方向</strong></label><select id="legion-strategy" :value="state.strategy" @change="session.mutate(s=>s.strategy=($event.target as HTMLSelectElement).value as LegionStrategy)"><option v-for="strategy in LEGION_STRATEGIES" :key="strategy.id" :value="strategy.id">{{strategy.name}}</option></select>
        <p class="legion-strategy-desc">{{LEGION_STRATEGIES.find(x=>x.id===state.strategy)?.detail}}</p>
        <label class="legion-toggle"><input type="checkbox" aria-label="自动进入下一关" :checked="state.options.advance" @change="session.mutate(s=>s.options.advance=($event.target as HTMLInputElement).checked)"><span>自动进入下一关</span></label>
        <p class="legion-strategy-desc">召兵、训练和强化由你决定。<br>编队 {{legionSlots(state)}} / 24 人，阵亡名额过关复活。</p>
        <div class="legion-command-list">
          <button v-for="(command,id) in LEGION_COMMANDS" :key="id" class="button legion-command" :disabled="state.paused||state.phase!=='battle'||state.essence<command.cost||(id==='assault'?state.commands.assaultCooldown:state.commands.healCooldown)>0||(id==='heal'&&!state.allies.some(a=>a.hp<a.maxHP))" @click="session.mutate(s=>{commandLegion(s,id)})"><strong>{{command.name}} · {{command.cost}} 精华</strong><span>{{command.detail}}</span><small>{{(id==='assault'?state.commands.assaultCooldown:state.commands.healCooldown)>0?`冷却 ${Math.ceil(id==='assault'?state.commands.assaultCooldown:state.commands.healCooldown)} 秒`:id==='assault'&&state.commands.assault>0?'强攻生效中':'点击施放'}}</small></button>
        </div>
        <div class="legion-combos"><strong>当前组合 · {{state.rank}}级</strong><p v-if="!Object.keys(state.cards).length">经验升级后获得强化次数，由你选择技能。</p><span v-for="card in LEGION_CARDS.filter(c=>legionCardLevel(state,c.id)>0).slice(0,6)" :key="card.id" :title="card.detail">{{card.name}} <b>{{legionCardLevel(state,card.id)}}</b></span></div>
        <button class="button legion-pending" :class="{primary:state.pending>0}" :disabled="state.paused||state.phase==='recover'" @click="panel='skills'">选择强化（{{state.pending}}）</button>
        <div class="legion-next-slot"><button v-if="state.phase!=='battle'" class="button primary legion-pending" :disabled="state.paused" @click="session.mutate(s=>{advanceLegion(s)})">{{state.phase==='recover'?'重新出征':'立即进入下一关'}}</button></div>
      </aside>
    </div>
    <div class="legion-roster" aria-label="六兵种军团">
      <div v-for="u in LEGION_UNITS" :key="u.id" class="legion-unit-card" :class="{locked:!legionUnlocked(state,u.id),selected:panel==='army'&&selected===u.id}">
        <button class="legion-unit-inspect" :aria-label="`查看${u.name}详情`" @click="chooseUnit(u.id)"><svg viewBox="-35 -72 78 82" aria-hidden="true"><LegionFigure :kind="u.id" :tier="1+Math.floor(state.training[u.id]/5)"/></svg><span><strong>{{u.name}}</strong><small>{{legionUnlocked(state,u.id)?`训练 Lv.${state.training[u.id]}`:`第 ${u.unlock} 关解锁`}}</small><em>{{state.allies.filter(a=>a.kind===u.id).length}}/{{state.formation[u.id]}} 人 · {{u.role}}</em></span></button>
        <button class="button" :aria-label="`召唤${u.name}`" :disabled="!canSummon(u.id)" @click="session.mutate(s=>{summonLegion(s,u.id)})">召唤 · {{u.cost}} 精华</button>
        <button class="button" :aria-label="`训练${u.name}`" :disabled="state.paused||!legionUnlocked(state,u.id)||state.coins<legionTrainingCost(state,u.id)||state.training[u.id]>=300" @click="session.mutate(s=>{trainLegion(s,u.id)})">训练 · {{format(legionTrainingCost(state,u.id))}} 金币</button>
      </div>
    </div>
    <footer class="legion-footer"><span class="legion-running">{{state.paused?'已暂停':state.phase==='recover'?'等待重新出征':state.phase==='march'&&!state.options.advance?'等待进入下一关':'军团正在自动作战'}} · 收起后继续作战，资源由你分配</span><div><button class="button" :aria-expanded="panel==='army'" @click="togglePanel('army')">军团配置</button><button class="button" :aria-expanded="panel==='log'" @click="togglePanel('log')">成长记录</button><button class="button" :aria-expanded="panel==='rules'" @click="togglePanel('rules')">玩法说明</button><button class="button" @click="togglePause">{{state.paused?'继续远征':'暂停远征'}}</button></div></footer>
    <section v-if="panel" ref="detailPanel" class="legion-detail" :aria-label="panel==='army'?'军团详细配置':panel==='skills'?'选择军团强化':panel==='log'?'成长记录':'玩法说明'">
      <div class="legion-detail-heading"><strong>{{panel==='army'?`${selectedUnit.name} · ${selectedUnit.role}`:panel==='skills'?`手动强化 · 剩余 ${state.pending} 次`:panel==='log'?'成长记录':'远征指挥说明'}}</strong><button class="button" @click="panel=null">收起详情</button></div>
      <template v-if="panel==='army'">
        <p>{{selectedUnit.detail}}</p><div class="legion-stat-grid"><span>最大生命 <b>{{format(selectedStats.hp)}}</b></span><span>单次攻击 / 治疗 <b>{{format(selectedStats.damage)}}</b></span><span>攻击 / 治疗频率 <b>{{selectedStats.rate.toFixed(2)}} 次/秒</b></span><span>攻击射程 <b>{{format(selectedStats.range)}}</b></span><span>护甲减伤 <b>{{(selectedStats.armor/(1+selectedStats.armor)*100).toFixed(1)}}%</b></span><span>训练等级 <b>{{state.training[selected]}} / 300</b></span></div>
        <button class="button" :disabled="state.paused||!legionUnlocked(state,selected)||state.coins<legionTrainingCost(state,selected)||state.training[selected]>=300" @click="session.mutate(s=>{trainLegion(s,selected)})">训练一级 · {{format(legionTrainingCost(state,selected))}} 金币</button>
        <p>训练永久保留，同一兵种共享训练属性。召唤添加新名额，不能重复使用本关阵亡名额；编队最多24人。每次召唤有短暂公共等待，当前剩余 {{state.recruitClock.toFixed(1)}} 秒。</p>
        <button class="button" :disabled="state.paused||state.phase==='recover'" @click="panel='skills'">选择强化 · 剩余 {{state.pending}} 次</button>
      </template>
      <template v-else-if="panel==='skills'"><p>每次选择消耗1次，可连续选择。当前构筑方向的技能排在前面，仅供参考，不会自动选择；战斗持续进行，需要思考时可先暂停观察。</p><div class="legion-card-list"><button v-for="card in skillCards" :key="card.id" class="legion-skill" :disabled="state.paused||state.phase==='recover'||!state.pending||legionCardLevel(state,card.id)>=10000||(card.family==='elements'&&!legionUnlocked(state,'mage'))||(card.id==='heal'&&!legionUnlocked(state,'priest'))||(card.id==='stomp'&&!legionUnlocked(state,'giant'))" @click="session.mutate(s=>{strengthenLegion(s,card.id)})"><strong>{{card.name}} · {{legionCardLevel(state,card.id)}}级</strong><span>{{card.detail}}</span><small v-if="card.family==='elements'&&!legionUnlocked(state,'mage')">需要第3关解锁法师</small><small v-else-if="card.id==='heal'&&!legionUnlocked(state,'priest')">需要第5关解锁祭司</small><small v-else-if="card.id==='stomp'&&!legionUnlocked(state,'giant')">需要第8关解锁巨人</small></button></div></template>
      <template v-else-if="panel==='log'"><div class="legion-stat-grid"><span>最高到达 <b>第{{state.bestWave}}关</b></span><span>累计胜利 <b>{{state.wins}}</b></span><span>累计击杀 <b>{{format(state.kills)}}</b></span><span>远征结算 <b>{{state.defeats}}次</b></span><span>累计有效伤害 <b>{{format(state.damage)}}</b></span><span>累计有效治疗 <b>{{format(state.healing)}}</b></span></div><ol><li v-for="(line,i) in state.log" :key="i">{{line}}</li></ol></template>
      <template v-else><p>单位自动移动、攻击和拾取；挂机开关只控制自动进入下一关。召兵、强化、永久训练以及失败后重新出征均由玩家操作。每5关有精英、每10关有首领，四种区域轮换。</p><p>点击兵种下的召唤按钮添加编队名额，消耗精华；阵亡名额仍占编队，不能反复补兵。本关阵亡在下一关满血复活，存活单位恢复30%生命。前排、远程、法术与治疗的比例由你选择。</p><p>金币用于永久训练；精华用于召兵和战场指令，战斗中自动恢复。经验升级后强化次数累积，点击选择强化可连续选择24种技能，构筑方向只调整推荐顺序。</p><p>强攻号令消耗20精华，全军攻击与治疗提高25%、持续6秒，冷却18秒；战地救援消耗20精华，恢复存活友军20%生命，冷却22秒。救援不复活阵亡单位，全员健康时不会消耗精华。</p><p>失败或同一关超过120秒会结算，保留金币、训练和解锁，本轮强化重置，回退约25%关卡。失败后等待你调整训练并点击重新出征，只补充基础6人小队，其余兵种手动召唤。</p><p>收起窗口、切换页面或切到其他软件仍继续战斗，但不花资源、不选强化；关闭自动过关则等待你点击下一关。点暂停才停止计时，退出后保存且不补算离线收益，支持1倍和2倍速度。</p><p>编队最多24人、双方同屏合计最多56人，攻击频率最多每秒12次，训练最高300级、单项强化最高10000级。范围与穿透只命中实际在场目标，护甲按递减收益结算，多个盾卫光环不叠加。</p></template>
    </section>
    <p class="legion-save-note">本机自动保存 · 最高第 {{state.bestWave}} 关 · 重新远征保留金币和永久训练</p>
  </div>
</template>
<style scoped>
